fn window(
    memory: &[u8],
    offset: usize,
    len: usize,
) -> Option<&[u8]> {
    let end = offset.checked_add(len)?;
    memory.get(offset..end)
}
fn main() {
    assert_eq!(
        window(b"crab", 1, 2),
        Some(&b"ra"[..])
    );
    assert_eq!(
        window(b"crab", usize::MAX, 2),
        None
    );
}

